def prepare_task(benchmark_dir, python="python"):
    """ Run prepare.py in the scripts folder of the benchmark if it exists and has not been run yet. """
    if os.path.exists(os.path.join(benchmark_dir, "scripts", "prepare.py")) and not os.path.exists(os.path.join(benchmark_dir, "scripts", "prepared")):
        print("Running prepare.py ...")
        p = subprocess.run([python, "prepare.py"], cwd=os.path.join(benchmark_dir,"scripts"))
        if p.returncode != 0:
            print("prepare.py failed")
            sys.exit(1)
        else:
            with open(os.path.join(benchmark_dir, "scripts", "prepared"), "w") as f:
                f.write("success")
        print("prepare.py finished")
    else:
        print("prepare.py not found or already prepared")

def check_file_read_only(arg_names, **kwargs):
    """ This decorator checks if the file is read-only. """

    def inner(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            new_kwargs = normalize_args_kwargs(func, *args, **kwargs)
            for arg_name in arg_names:
                if new_kwargs[arg_name] in new_kwargs["kwargs"]["read_only_files"]:
                    raise EnvException(f"cannot write file {new_kwargs[arg_name]} because it is a read-only file.")
            return func(*args, **kwargs)
        return wrapper
    return inner


def check_file_in_work_dir(arg_names, **kwargs):
    """ This decorator checks if the file is in the work directory. """
    def inner(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            new_kwargs = normalize_args_kwargs(func, *args, **kwargs)
            work_dir = new_kwargs["work_dir"]
            for arg_name in arg_names:
                file_name = new_kwargs[arg_name]
                if not os.path.abspath(os.path.join(work_dir, file_name)).startswith(os.path.abspath(work_dir)):
                    raise EnvException(f"cannot access file {file_name} because it is not in the work directory.")
            return func(*args, **kwargs)
        return wrapper
    return inner


